1	import { AllInvoicesToolbar } from '../../slots/defs/allInvoicesToolbar';
2	import { useSearchParam, asString } from '../../url/useSearchParam';
3	import { formatMoney } from '../../ui/money';
4	import { useAllInvoices } from './allInvoices';
5	
6	// One place listing every invoice from every project. Reads its own query key and shows, per row,
7	// which project the invoice is for and what stage (status) it is at. When the shared `invoiceStatus`
8	// URL key (set by a toolbar control) names a stage, the list keeps only the rows at that stage.
9	export function AllInvoiceList() {
10	  const { data: invoices } = useAllInvoices();
11	  const [status] = useSearchParam('invoiceStatus', asString);
12	
13	  if (!invoices) {
14	    return null;
15	  }
16	
17	  if (invoices.length === 0) {
18	    return <p data-testid="all-invoices-empty">No invoices yet.</p>;
19	  }
20	
21	  const shown = status ? invoices.filter((invoice) => invoice.status === status) : invoices;
22	
23	  return (
24	    <>
25	    <AllInvoicesToolbar.Slot />
26	    <table data-testid="all-invoices-table">
27	      <thead>
28	        <tr>
29	          <th>Project</th>
30	          <th>Amount</th>
31	          <th>Stage</th>
32	        </tr>
33	      </thead>
34	      <tbody>
35	        {shown.map((invoice) => (
36	          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
37	            <td data-testid="invoice-project">{invoice.projectName}</td>
38	            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
39	            <td data-testid="invoice-status">{invoice.status}</td>
40	          </tr>
41	        ))}
42	      </tbody>
43	    </table>
44	    </>
45	  );
46	}
